import type { ButtonHTMLAttributes } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const filledShadow = "shadow-[inset_0_1px_0_rgba(255,255,255,0.14)]";

/* Pill-shaped by default: the app's core button style. Explicit symmetric
 * padding (not a fixed height) so the top/bottom spacing is always equal. */
export const buttonVariants = cva(
  `inline-flex items-center justify-center font-medium select-none
   transition-[transform,background-color,opacity] duration-150 ease-out
   active:scale-[0.96] disabled:opacity-50 disabled:pointer-events-none`,
  {
    variants: {
      variant: {
        primary: `bg-ink text-canvas hover:opacity-90 dark:bg-ink dark:text-canvas ${filledShadow}`,
        secondary: "bg-surface text-ink shadow-btn hover:bg-inset aria-expanded:bg-hover",
        ghost: "bg-hover-2 text-ink hover:bg-line-strong",
        accent: `bg-accent-blue text-white hover:bg-accent-ink ${filledShadow}`,
        danger: `bg-red text-white hover:brightness-95 ${filledShadow}`,
        /* transparent until hovered: for dense toolbars/action rows */
        quiet: "text-ink hover:bg-hover",
      },
      size: {
        /* compact toolbar pill: fixed height, lighter weight */
        xs: "h-7 rounded-full px-2.5 text-[12px] font-normal leading-none gap-1",
        /* canonical action pill: 27px tall, roomy sides */
        sm: "h-[27px] px-3 text-[13px] leading-none rounded-full gap-1.5",
        md: "px-4 py-[9px] text-sm leading-none rounded-full gap-2",
      },
    },
    defaultVariants: { variant: "secondary", size: "md" },
  },
);

export type ButtonVariant = NonNullable<VariantProps<typeof buttonVariants>["variant"]>;

export function Button({ variant, size, className, ...props }: ButtonHTMLAttributes<HTMLButtonElement> & VariantProps<typeof buttonVariants>) {
  return <button type="button" className={cn(buttonVariants({ variant, size }), className)} {...props} />;
}

import { useRef, useState, type ReactNode } from "react";

type GlideMenuProps = {
  children: ReactNode;
  className?: string;
  highlightClassName?: string;
  rowSelector?: string;
};

/** A single hover layer that glides between interactive menu rows. */
export default function GlideMenu({
  children,
  className = "",
  highlightClassName = "inset-x-0 rounded-[8px] bg-hover",
  rowSelector = "[data-menu-row]",
}: GlideMenuProps) {
  const ref = useRef<HTMLDivElement>(null);
  const [box, setBox] = useState<{ top: number; height: number } | null>(null);
  const [visible, setVisible] = useState(false);

  const moveTo = (target: EventTarget | null) => {
    const container = ref.current;
    if (!(target instanceof Element) || !container) return;
    const row = target.closest(rowSelector);
    if (!(row instanceof HTMLElement) || !container.contains(row)) return;
    const containerRect = container.getBoundingClientRect();
    const rowRect = row.getBoundingClientRect();
    setBox({ top: rowRect.top - containerRect.top, height: rowRect.height });
    setVisible(true);
  };

  return (
    <div
      ref={ref}
      onMouseOver={(event) => moveTo(event.target)}
      onMouseLeave={() => setVisible(false)}
      onFocusCapture={(event) => moveTo(event.target)}
      onBlurCapture={(event) => {
        if (!ref.current?.contains(event.relatedTarget as Node | null)) setVisible(false);
      }}
      className={`group/glide-menu relative ${className}`}
    >
      <span
        aria-hidden
        className={`pointer-events-none absolute ${highlightClassName}`}
        style={{
          top: box?.top ?? 0,
          height: box?.height ?? 0,
          opacity: box && visible ? 1 : 0,
          transition:
            "top 220ms cubic-bezier(0.23,1,0.32,1), height 220ms cubic-bezier(0.23,1,0.32,1), opacity 150ms ease",
        }}
      />
      {children}
    </div>
  );
}

import { useEffect, useState } from "react";

/* ---------------------------------------------------------
 * LOADING STATE: pixel-grid loader for long-running work
 *
 *   Drive: square cells, a chevron wavefront driving right
 *   Dots:  the same wavefront, circular cells
 *   Orbit: a comet lapping the grid perimeter
 *
 * Paired with a shimmering label and the time elapsed since
 * `since` (epoch ms; by default since it appeared), in mono
 * tabular figures.
 * --------------------------------------------------------- */

const chevron = Array.from({ length: 9 }, (_, i) => {
  const r = Math.floor(i / 3),
    c = i % 3;
  return (c + Math.abs(r - 1)) * 90;
});

const ORBIT_ORDER = [0, 1, 2, 5, 8, 7, 6, 3];
const orbit = Array.from({ length: 9 }, (_, i) => {
  const k = ORBIT_ORDER.indexOf(i);
  return k === -1 ? null : k * 110;
});

const PATTERNS: Record<string, { delays: (number | null)[]; dur: number; round: boolean }> = {
  Drive: { delays: chevron, dur: 650, round: false },
  Dots: { delays: chevron, dur: 650, round: true },
  Orbit: { delays: orbit, dur: 950, round: false },
};

export function LoaderGrid({ variant = "Dots" }: { variant?: string }) {
  const { delays, dur, round } = PATTERNS[variant] ?? (PATTERNS.Dots as (typeof PATTERNS)[string]);
  return (
    <span aria-hidden className="grid shrink-0 grid-cols-[repeat(3,4px)] gap-[1.5px]">
      {delays.map((delay, index) => (
        <span
          key={index}
          className={`size-[4px] bg-ink ${round ? "rounded-full" : "rounded-[1px]"}`}
          style={{
            opacity: delay === null ? 0.07 : 0.15,
            animation: delay === null ? "none" : `pixel-on ${dur}ms ease-in-out ${delay}ms infinite`,
          }}
        />
      ))}
    </span>
  );
}

function useElapsed(since: number | undefined) {
  const [start] = useState(() => since ?? Date.now());
  const [now, setNow] = useState(() => Date.now());
  useEffect(() => {
    const t = setInterval(() => setNow(Date.now()), 100);
    return () => clearInterval(t);
  }, []);
  const total = Math.max(0, now - start) / 1000;
  if (total < 60) return `${total.toFixed(1)}s`;
  return `${Math.floor(total / 60)}m ${(total % 60).toFixed(1)}s`;
}

export default function LoadingState({ label = "Working", variant = "Dots", since }: { label?: string; variant?: string; since?: number }) {
  const elapsed = useElapsed(since);
  return (
    <div role="status" className="flex w-fit items-center gap-2.5">
      <LoaderGrid variant={variant} />
      <span
        className="bg-clip-text text-[13px] font-medium text-transparent"
        style={{
          backgroundImage: "linear-gradient(90deg, var(--ink-3) 35%, var(--ink) 50%, var(--ink-3) 65%)",
          backgroundSize: "200% 100%",
          animation: "shimmer-text 1.4s linear infinite",
        }}
      >
        {label}
      </span>
      <span className="font-mono text-[12px] text-ink-3 tabular-nums">{elapsed}</span>
    </div>
  );
}

import { useEffect, useLayoutEffect, useRef, useState, type ReactNode } from "react";

/* ---------------------------------------------------------
 * PROMPT BAR
 * Beautiful UI's hero composer: a multi-line input with its
 * controls on their own row. Here its picker chooses something
 * real (an agent) or names it, and while a run goes the send
 * button stops it. Enter sends, Shift+Enter breaks a line.
 * --------------------------------------------------------- */

function Icon({ children, size = 15, strokeWidth = 1.8 }: { children: ReactNode; size?: number; strokeWidth?: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
      {children}
    </svg>
  );
}

export type PickerOption = { key: string; name: string; tag?: string };

export type Picker = {
  /** what it chooses, for its label: "agent" */
  label: string;
  options: PickerOption[];
  value: string | undefined;
  /** absent: the value is shown, not chosen */
  onChange?: (key: string) => void;
};

export default function PromptBar({
  placeholder,
  picker,
  onSend,
  busy = false,
  onStop,
  disabled = false,
  autoFocus = false,
}: {
  placeholder?: string;
  picker?: Picker;
  /** sends the text; the draft is cleared once it resolves, kept when it throws */
  onSend: (text: string) => Promise<void> | void;
  /** a run is going: with an empty draft, the send button stops it */
  busy?: boolean;
  onStop?: () => void;
  disabled?: boolean;
  autoFocus?: boolean;
}) {
  const [draft, setDraft] = useState("");
  const [sending, setSending] = useState(false);
  const [modelOpen, setModelOpen] = useState(false);
  const [modelBox, setModelBox] = useState<{ top: number; height: number } | null>(null);
  const [modelHovered, setModelHovered] = useState<number | null>(null);
  const [modelMenuLeft, setModelMenuLeft] = useState(0);
  const [modelMenuBottom, setModelMenuBottom] = useState(0);
  const composerAnchorRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const modelRef = useRef<HTMLButtonElement>(null);
  const modelRowRefs = useRef<(HTMLButtonElement | null)[]>([]);

  const options = picker?.options ?? [];
  const choosable = picker?.onChange !== undefined && options.length > 1;
  const chosen = options.find((option) => option.key === picker?.value);

  /* the gliding highlight floats to the hovered row, falling back to the chosen one */
  const modelIndex = options.findIndex((option) => option.key === picker?.value);
  useLayoutEffect(() => {
    if (!modelOpen) return;
    const target = modelRowRefs.current[modelHovered ?? modelIndex];
    if (target) setModelBox({ top: target.offsetTop, height: target.offsetHeight });
  }, [modelOpen, modelHovered, modelIndex]);

  /* the menu sits outside the clipped composer: align it to the trigger by measurement */
  useLayoutEffect(() => {
    if (!modelOpen || !composerAnchorRef.current || !modelRef.current) return;
    const anchorRect = composerAnchorRef.current.getBoundingClientRect();
    const triggerRect = modelRef.current.getBoundingClientRect();
    setModelMenuLeft(Math.max(0, Math.min(triggerRect.left - anchorRect.left, anchorRect.width - 176)));
    setModelMenuBottom(anchorRect.bottom - triggerRect.top + 8);
  }, [modelOpen]);

  useEffect(() => {
    if (!modelOpen) setModelHovered(null);
  }, [modelOpen]);

  /* grow with the text, to a compact maximum */
  useLayoutEffect(() => {
    const input = inputRef.current;
    if (!input) return;
    const maxHeight = 200;
    input.style.height = "0px";
    const contentHeight = input.scrollHeight;
    input.style.height = `${Math.min(contentHeight, maxHeight)}px`;
    input.style.overflowY = contentHeight > maxHeight ? "auto" : "hidden";
  }, [draft]);

  /* clicking anywhere outside the composer closes the menu */
  useEffect(() => {
    if (!modelOpen) return;
    const close = (event: PointerEvent) => {
      if (!(event.target as Element).closest("[data-promptbar]")) setModelOpen(false);
    };
    document.addEventListener("pointerdown", close);
    return () => document.removeEventListener("pointerdown", close);
  }, [modelOpen]);

  const canSend = draft.trim().length > 0 && !sending && !disabled;
  const stopping = busy && onStop !== undefined && draft.trim().length === 0;

  const send = async () => {
    if (!canSend) return;
    setSending(true);
    setModelOpen(false);
    try {
      await onSend(draft.trim());
      setDraft("");
    } catch {
      // The caller says why; the draft stays.
    } finally {
      setSending(false);
      inputRef.current?.focus();
    }
  };

  return (
    <div data-promptbar className="w-full">
      <div ref={composerAnchorRef} className="relative">
        {/* -- picker menu -- */}
        {modelOpen && (
          <div
            onMouseLeave={() => setModelHovered(null)}
            className="absolute z-10 w-44 rounded-[10px] bg-surface p-1 shadow-raised"
            style={{ left: modelMenuLeft, bottom: modelMenuBottom, animation: "pop-in 180ms cubic-bezier(0.23,1,0.32,1) both", transformOrigin: "bottom left" }}
          >
            <span
              aria-hidden
              className="pointer-events-none absolute inset-x-1 rounded-[6px] bg-hover"
              style={{
                top: modelBox?.top ?? 0,
                height: modelBox?.height ?? 0,
                opacity: modelBox && modelHovered !== null ? 1 : 0,
                transition: "top 220ms cubic-bezier(0.23,1,0.32,1), height 220ms cubic-bezier(0.23,1,0.32,1), opacity 150ms ease",
              }}
            />
            {options.map((option, i) => (
              <button
                key={option.key}
                type="button"
                role="option"
                aria-selected={option.key === picker?.value}
                ref={(el) => {
                  modelRowRefs.current[i] = el;
                }}
                onMouseDown={(event) => event.preventDefault()}
                onMouseEnter={() => setModelHovered(i)}
                onClick={() => {
                  picker?.onChange?.(option.key);
                  setModelOpen(false);
                  inputRef.current?.focus();
                }}
                className="relative z-10 flex h-7.5 w-full items-center gap-2 rounded-[6px] px-2 text-left"
              >
                <span className="min-w-0 flex-1 truncate text-[12.5px] font-medium text-ink">{option.name}</span>
                {option.tag !== undefined && <span className="shrink-0 text-[11px] text-ink-3">{option.tag}</span>}
                <span className={`shrink-0 text-ink ${option.key === picker?.value ? "" : "invisible"}`}>
                  <Icon size={13} strokeWidth={2.5}>
                    <path d="M20 6L9 17l-5-5" />
                  </Icon>
                </span>
              </button>
            ))}
          </div>
        )}

        {/* -- composer -- */}
        <div className="relative isolate flex flex-col gap-2.5 overflow-hidden rounded-[22px] border border-line bg-surface p-3.5 shadow-card transition-[border-color,border-radius] duration-150 focus-within:border-line-strong">
          <div className="grid grid-cols-[auto_minmax(0,1fr)_28px] items-end gap-x-1 gap-y-1.5">
            <textarea
              ref={inputRef}
              rows={1}
              value={draft}
              autoFocus={autoFocus}
              disabled={disabled}
              onChange={(event) => setDraft(event.target.value)}
              onKeyDown={(event) => {
                if (event.key === "Escape") {
                  setModelOpen(false);
                  return;
                }
                if (event.key === "Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {
                  event.preventDefault();
                  void send();
                }
              }}
              placeholder={placeholder ?? "Write a message…"}
              aria-label="Message"
              className="col-span-full col-start-1 row-start-1 min-h-[68px] w-full min-w-0 resize-none bg-transparent px-2 py-2 text-[14px] leading-5 text-ink outline-none [overflow-wrap:anywhere] placeholder:text-ink-3 disabled:opacity-60"
            />

            {/* picker */}
            {picker !== undefined ? (
              <button
                ref={modelRef}
                type="button"
                aria-expanded={choosable ? modelOpen : undefined}
                aria-label={choosable ? `Choose the ${picker.label}` : `The ${picker.label}`}
                disabled={!choosable}
                onClick={() => setModelOpen((current) => !current)}
                className="col-start-1 row-start-2 flex h-7 shrink-0 items-center gap-1 justify-self-start rounded-[8px] px-1.5 text-[12px] font-medium text-ink-2 transition-colors duration-150 enabled:hover:bg-hover enabled:hover:text-ink"
              >
                {chosen?.name ?? picker.value ?? `No ${picker.label}`}
                {choosable && (
                  <span className="text-ink-3">
                    <Icon size={11} strokeWidth={2.4}>
                      <path d="M6 9l6 6 6-6" />
                    </Icon>
                  </span>
                )}
              </button>
            ) : (
              <span className="col-start-1 row-start-2" />
            )}

            {/* send, or stop while a run goes */}
            <button
              type="button"
              aria-label={stopping ? "Stop the run" : "Send"}
              title={stopping ? "Stop the run" : busy ? "Send: it runs after the run going" : "Send"}
              disabled={!stopping && !canSend}
              onClick={stopping ? onStop : () => void send()}
              className="col-start-3 row-start-2 flex size-7 shrink-0 items-center justify-center rounded-[8px] transition-[background-color,color,transform] duration-200 enabled:active:scale-[0.94]"
              style={{
                background: canSend || stopping ? "var(--ink)" : "var(--line-strong)",
                color: canSend || stopping ? "var(--surface)" : "var(--ink-2)",
              }}
            >
              {stopping ? (
                <svg width="10" height="10" viewBox="0 0 10 10" aria-hidden>
                  <rect width="10" height="10" rx="2" fill="currentColor" />
                </svg>
              ) : sending ? (
                <span className="size-3 rounded-full border-[1.5px] border-current border-t-transparent" style={{ animation: "spin 700ms linear infinite" }} />
              ) : (
                <Icon size={16} strokeWidth={2.4}>
                  <path d="M12 19V5M5 12l7-7 7 7" />
                </Icon>
              )}
            </button>
          </div>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef, useState, type CSSProperties, type MouseEvent, type ReactNode } from "react";
import { createPortal } from "react-dom";
import { NavArrowDown, Search, SidebarCollapse, Xmark } from "iconoir-react";
import GlideMenu from "./GlideMenu";

/* ---------------------------------------------------------
 * SIDEBAR NAV
 * Beautiful UI's harness sidebar, fed by the app: a workspace
 * menu, primary navigation, a searchable list of chats, and a
 * collapse that keeps every icon in place. Icons: iconoir.
 * --------------------------------------------------------- */

export type SidebarItem = {
  key: string;
  label: string;
  icon: ReactNode;
  /** a short figure at the row's end */
  count?: string;
  active?: boolean;
  /** the link's target, for a new tab; a plain click calls `onSelect` */
  href?: string;
  onSelect: () => void;
};

export type SidebarChat = {
  id: string;
  label: string;
  /** what it is, at the row's end: its channel */
  meta?: string;
  busy?: boolean;
  active?: boolean;
  href?: string;
};

const SIDEBAR_MOTION = {
  expandedWidth: 224,
  collapsedWidth: 52,
  duration: 280,
  copyDuration: 180,
  copyOffset: 8,
  easing: "cubic-bezier(0.16, 1, 0.3, 1)",
};

const CHAT_SEARCH_MOTION = {
  duration: 180,
  closedWidth: 28,
  easing: "cubic-bezier(0.16, 1, 0.3, 1)",
};

/** A plain left click follows `onSelect`; any other (a new tab) follows the link. */
function follow(event: MouseEvent, onSelect: () => void) {
  if (event.button !== 0 || event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) return;
  event.preventDefault();
  onSelect();
}

function GlideGroup({ children }: { children: ReactNode }) {
  return (
    <GlideMenu rowSelector="[data-row]" highlightClassName="sidebar-glide-highlight rounded-[7px] bg-hover-2" className="group/glide flex flex-col gap-px">
      {children}
    </GlideMenu>
  );
}

function RailButton({ item }: { item: SidebarItem }) {
  const { icon, label, active = false, count, href, onSelect } = item;
  return (
    <a
      data-row
      href={href}
      onClick={(event) => follow(event, onSelect)}
      aria-current={active ? "page" : undefined}
      title={label}
      className={`sidebar-row relative z-10 mx-2 flex h-8 items-center rounded-[8px] px-2 text-left transition-[width,background-color,color,transform] duration-150 active:scale-[0.98] ${active ? "bg-hover-2 group-hover/glide:bg-transparent" : ""}`}
    >
      <span className={`flex size-5 shrink-0 items-center justify-center [&_svg]:size-[18px] ${active ? "text-ink" : "text-ink-2"}`}>{icon}</span>
      <span className={`sidebar-copy ml-1.5 min-w-0 flex-1 truncate text-[14px] font-medium ${active ? "text-ink" : "text-ink-2"}`}>{label}</span>
      {count && <span className="sidebar-copy mr-2 shrink-0 text-[12px] font-medium tabular-nums text-ink-3">{count}</span>}
    </a>
  );
}

/** One row of the workspace menu. */
export function MenuRow({ icon, children, trailing, onClick, height = "h-9" }: { icon?: ReactNode; children: ReactNode; trailing?: ReactNode; onClick?: () => void; height?: string }) {
  return (
    <button data-menu-row type="button" onClick={onClick} className={`relative z-10 flex ${height} w-full items-center gap-1.5 rounded-[8px] px-2 text-left`}>
      {icon !== undefined && <span className="flex size-5 shrink-0 items-center justify-center text-ink-2 [&_svg]:size-4">{icon}</span>}
      <span className="min-w-0 flex-1 truncate text-[13.5px] text-ink">{children}</span>
      {trailing}
    </button>
  );
}

export function MenuSeparator() {
  return <div className="my-1 h-px bg-line" />;
}

function WorkspaceMenu({ position, children }: { position: { top: number; left: number }; children: ReactNode }) {
  return createPortal(
    <div
      data-workspace-menu
      className="fixed z-50 w-64 rounded-[14px] bg-surface p-1.5 shadow-overlay"
      style={{ top: position.top, left: position.left, animation: "pop-in 180ms cubic-bezier(0.23,1,0.32,1) both", transformOrigin: "top left" }}
    >
      <GlideMenu className="flex flex-col gap-px" highlightClassName="inset-x-0 rounded-[8px] bg-hover-2">
        {children}
      </GlideMenu>
    </div>,
    document.body,
  );
}

export default function SidebarNav({
  workspace,
  menu,
  items,
  chats,
  onPickChat,
  chatsFooter,
  chatsEmpty = "No chats yet",
  defaultCollapsed = false,
  className = "",
}: {
  workspace: { name: string; logo: ReactNode };
  /** the workspace menu's rows (`MenuRow`, `MenuSeparator`); `close` closes it */
  menu: (close: () => void) => ReactNode;
  items: SidebarItem[];
  chats: SidebarChat[];
  onPickChat: (id: string) => void;
  /** after the chats: "older" */
  chatsFooter?: ReactNode;
  chatsEmpty?: string;
  defaultCollapsed?: boolean;
  className?: string;
}) {
  const [collapsed, setCollapsed] = useState(defaultCollapsed);
  const [workspaceOpen, setWorkspaceOpen] = useState(false);
  const [workspacePosition, setWorkspacePosition] = useState({ top: 0, left: 0 });
  const [chatsOpen, setChatsOpen] = useState(true);
  const [searchOpen, setSearchOpen] = useState(false);
  const [query, setQuery] = useState("");
  const workspaceButtonRef = useRef<HTMLButtonElement>(null);
  const searchRef = useRef<HTMLInputElement>(null);

  const needle = query.trim().toLowerCase();
  const visibleChats = chats.filter((chat) => `${chat.label} ${chat.meta ?? ""}`.toLowerCase().includes(needle));

  useEffect(() => {
    if (!workspaceOpen) return;
    const close = (event: PointerEvent) => {
      const target = event.target as Element;
      if (!target.closest("[data-workspace-trigger]") && !target.closest("[data-workspace-menu]")) setWorkspaceOpen(false);
    };
    const escape = (event: KeyboardEvent) => event.key === "Escape" && setWorkspaceOpen(false);
    document.addEventListener("pointerdown", close);
    document.addEventListener("keydown", escape);
    return () => {
      document.removeEventListener("pointerdown", close);
      document.removeEventListener("keydown", escape);
    };
  }, [workspaceOpen]);

  useEffect(() => {
    if (searchOpen) searchRef.current?.focus();
  }, [searchOpen]);

  const collapse = () => {
    setCollapsed(true);
    setWorkspaceOpen(false);
    setSearchOpen(false);
    setQuery("");
  };

  return (
    <aside
      data-sidebar-collapsed={collapsed}
      aria-label="Navigation"
      className={`relative flex h-full shrink-0 overflow-hidden transition-[width] ${className}`}
      style={
        {
          width: collapsed ? SIDEBAR_MOTION.collapsedWidth : SIDEBAR_MOTION.expandedWidth,
          transitionDuration: `${SIDEBAR_MOTION.duration}ms`,
          transitionTimingFunction: SIDEBAR_MOTION.easing,
          "--sidebar-copy-duration": `${SIDEBAR_MOTION.copyDuration}ms`,
          "--sidebar-copy-offset": `${SIDEBAR_MOTION.copyOffset}px`,
          "--sidebar-easing": SIDEBAR_MOTION.easing,
        } as CSSProperties
      }
    >
      <div className="flex min-h-0 w-[224px] shrink-0 flex-col">
        <div className="relative mb-2.5 h-10 shrink-0">
          <button
            ref={workspaceButtonRef}
            data-workspace-trigger
            type="button"
            aria-expanded={workspaceOpen}
            aria-hidden={collapsed}
            tabIndex={collapsed ? -1 : 0}
            onClick={() => {
              if (!workspaceOpen && workspaceButtonRef.current) {
                const rect = workspaceButtonRef.current.getBoundingClientRect();
                setWorkspacePosition({ top: rect.bottom + 6, left: rect.left });
              }
