import type { ReactNode } from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";

const statusPillVariants = cva("inline-flex h-6 items-center gap-1.5 rounded-full px-2.5 text-[13px] font-medium leading-none", {
  variants: {
    tone: {
      green: "bg-green-tint text-green",
      orange: "bg-orange-tint text-orange",
      red: "bg-red-tint text-red",
      accent: "bg-accent-tint text-accent-ink",
      neutral: "bg-inset text-ink-2",
    },
  },
  defaultVariants: { tone: "neutral" },
});

export type Tone = NonNullable<VariantProps<typeof statusPillVariants>["tone"]>;

/* the leading dot lives on a separate element, so its color stays a small lookup */
const dotColor: Record<Tone, string> = {
  green: "bg-green",
  orange: "bg-orange",
  red: "bg-red",
  accent: "bg-accent-blue",
  neutral: "bg-ink-3",
};

export function StatusPill({ tone = "neutral", children, dot = true, className }: { tone?: Tone; children: ReactNode; dot?: boolean; className?: string }) {
  return (
    <span className={cn(statusPillVariants({ tone }), className)}>
      {dot && <span className={cn("size-1.5 rounded-full", dotColor[tone])} />}
      {children}
    </span>
  );
}

/* ---------------------------------------------------------
 * STREAM TEXT
 * Beautiful UI's streaming atom, fed by a live stream instead of a
 * timer: `text` is what arrived so far. While `streaming`, the
 * newest characters resolve out of a soft blur and the caret holds
 * solid; once settled the text stands alone. Inherits typography.
 * --------------------------------------------------------- */

export function StreamText({
  text,
  streaming,
  blurTail = 6,
  className,
}: {
  text: string;
  streaming: boolean;
  /** how many trailing characters carry the soft blur edge */
  blurTail?: number;
  className?: string;
}) {
  const split = streaming ? Math.max(0, text.length - blurTail) : text.length;
  return (
    <span className={className}>
      {text.slice(0, split)}
      {split < text.length && <span className="stream-tail">{text.slice(split)}</span>}
      {streaming && <span aria-hidden className="stream-caret is-streaming" />}
    </span>
  );
}

/** A switch: `md` is Beautiful UI's atom, `sm` the harness's compact one (for menu rows). */
export function Switch({ checked, onChange, label, size = "md" }: { checked: boolean; onChange?: (value: boolean) => void; label?: string; size?: "sm" | "md" }) {
  const small = size === "sm";
  return (
    <span
      role="switch"
      aria-checked={checked}
      aria-label={label}
      tabIndex={onChange === undefined ? -1 : 0}
      onClick={onChange === undefined ? undefined : () => onChange(!checked)}
      onKeyDown={(event) => {
        if (onChange !== undefined && (event.key === " " || event.key === "Enter")) {
          event.preventDefault();
          onChange(!checked);
        }
      }}
      className={`relative inline-block shrink-0 rounded-full align-middle transition-colors duration-200 ${small ? "h-4.5 w-7.5" : "h-6 w-10"} ${checked ? (small ? "bg-accent-blue" : "bg-ink") : "bg-line-strong"}`}
    >
      <span
        className={`absolute top-0.5 left-0.5 rounded-full bg-white shadow-[0_1px_2px_rgba(0,0,0,0.2)] transition-transform duration-200 ${small ? "size-3.5" : "size-5"}`}
        style={{
          transform: checked ? `translateX(${small ? 12 : 16}px)` : "translateX(0)",
          transitionTimingFunction: "cubic-bezier(0.23, 1, 0.32, 1)",
        }}
      />
    </span>
  );
}

